// This file is generated by AI.

// 磁盘变更同步: 打开中的文档与磁盘之间的**唯一**同步点。
//
// 背景: 打开中的文档有三份"内容" —— 磁盘上的、我们上次知道磁盘内容的基准、以及编辑器里现在
// 这一份。除了配音卡 (它只在自己处于配音模式且是活动文档时轮询) 之外, 没有任何机制把磁盘上的
// 变化送进编辑器。后果不是"界面没刷新"这么轻: 用户继续编辑时自动保存会把内存里的旧内容写回
// 磁盘, **静默吃掉**外部改动或刚还原出来的内容。
//
// 这里的规则只有三条 (判据见 `editor/disk-state.ts`):
//
// 1. **没有未保存改动** -> 直接重读磁盘, 覆盖编辑器, 不打扰用户;
// 2. **有未保存改动** -> 记一条冲突, 由活动文档那个对话框裁决;
// 3. **磁盘上就是编辑器里这一份** -> 只对齐基准 (多半是我们自己刚写盘 / 别处写了同样内容)。
//
// 三条配套的硬约束, 缺一条这个机制就会反噬:
//
// * **冲突未裁决时该文档的自动保存要暂停** (`isDiskBlocked`): 否则对话框还开着, 800ms 后的
//   自动保存就把内存那份写回磁盘 —— "加载磁盘内容"会加载到用户自己刚写的旧内容;
// * **自写盘之后必须 `noteDiskContent`** (见 `ui/CodeEditor.svelte` 的 saver write、`unsaved.ts`、
//   跨文件重命名): 不记基准, 下一次检查就把自己的写入当成外部修改, 弹一个两个选项都没区别的
//   对话框;
// * **比较一律归一化换行** (由 `contentHash` 负责): Windows 上 CRLF 与 Monaco 回出来的 LF
//   不归一化, 每次自动保存都会变成一次"外部修改"。
//
// 触发来源有四种: 项目文件监听 (`lib/project-watch.ts`, 与 git 状态刷新共用一条)、窗口重新
// 聚焦、切换活动文档、以及我们自己的批量写盘动作之后 (还原 / 切分支 / 切模板) 直接调用
// `checkAllOpenDocuments`。**刻意不做常驻轮询**: 项目根上已经挂着监听, 周期性读盘纯属浪费。
//
// ⚠️ 配音卡不再自己检测磁盘 (那套 `checkDiskChange` 已删除), 否则同一个文件会弹两次对话框。
// 它改为订阅 `onExternalContent` 在内容被换掉之后重新对齐配音历史。

import { fs } from '../lib/fs';
import { onProjectFilesChanged, startProjectWatch } from '../lib/project-watch';
import { useAppStore } from '../state/store.svelte';
import { affectedDocumentPaths, contentHash, decideDiskAction, pathKey, previewOf } from './disk-state';

/** 一条待裁决的磁盘冲突。 */
export interface DiskConflict {
  path: string;
  /** 磁盘全文哈希 (归一化后)。**去重按它**, 不按预览: 预览只截了开头几行, 外部改动发生在后面时预览一模一样 */
  hash: string;
  /** 磁盘内容前若干行 (对话框里展示) */
  preview: string;
  /** 整份磁盘内容: 裁决时用它, 不再重读 —— 用户看到的与最终落下去的必须是同一份 */
  diskContent: string;
  /** 用户按过 Esc: 同一份磁盘内容不再追问, 但冲突仍然挂着 (自动保存继续暂停) */
  dismissed: boolean;
}

export type ConflictChoice = 'take-disk' | 'keep-editor' | 'backup-take-disk';

/** 响应式状态: 选项卡标记与冲突对话框读它。 */
export const diskSync: { conflicts: Record<string, DiskConflict>; activePath: string | null } = $state({
  conflicts: {},
  activePath: null,
});

/** 磁盘基准: 路径比较键 -> 我们已知磁盘上那一份的哈希 */
const baselines = new Map<string, string>();

/** 内容被磁盘换掉之后的订阅者 (配音卡用它重新解析 / 对齐) */
const contentListeners = new Set<(path: string) => void>();

let unsubscribeWatch: (() => void) | null = null;
let focusBound = false;
/** 检查串行排队: 监听事件、聚焦、显式调用可能挤在同一瞬间 */
let queue: Promise<void> = Promise.resolve();
let lastFocusCheck = 0;

/** 与基准比较用的密钥; 与 `pathKey` 同一个口径, 这里只是少打几个字。 */
function keyOf(path: string): string {
  return pathKey(path);
}

/**
 * 记下"磁盘上现在就是这一份内容"。
 *
 * 两个调用场景共用: **我们自己写盘之后** (先写盘再记, 顺序不能反) 与**刚开始读盘之后**
 * (打开文件)。两者都意味着"之前挂着的那条冲突作废", 因此这里会顺手清掉冲突记录 —— 但**不**
 * 发 `onExternalContent`: 调用方自己知道内容有没有真的换掉 (裁决、写盘各自处理)。
 */
export function noteDiskContent(path: string, text: string): void {
  const key = keyOf(path);
  baselines.set(key, contentHash(text));
  delete diskSync.conflicts[key];
}

/** 某文档是否处于"磁盘变了、还没裁决"的状态 —— 自动保存据此暂停。 */
export function isDiskBlocked(path: string): boolean {
  return Boolean(diskSync.conflicts[keyOf(path)]);
}

/** 该文档当前挂着的冲突 (没有则 null)。 */
export function conflictFor(path: string): DiskConflict | null {
  return diskSync.conflicts[keyOf(path)] ?? null;
}

/** 把冲突重新摆到用户面前 (Ctrl+S 撞上冲突时用; Esc 之后也靠它恢复提示)。 */
export function requestDiskAttention(path: string): void {
  const conflict = diskSync.conflicts[keyOf(path)];
  if (conflict) conflict.dismissed = false;
}

/** 用户选择"暂不决定": 同一份磁盘内容不再追问 (冲突仍挂着, 自动保存仍暂停)。 */
export function dismissDiskConflict(path: string): void {
  const conflict = diskSync.conflicts[keyOf(path)];
  if (conflict) conflict.dismissed = true;
}

/** 订阅"某个文档的内容被磁盘换掉了"。返回退订函数。 */
export function onExternalContent(listener: (path: string) => void): () => void {
  contentListeners.add(listener);
  return () => {
    contentListeners.delete(listener);
  };
}

function emitExternalContent(path: string): void {
  for (const listener of contentListeners) {
    try {
      listener(path);
    } catch (error) {
      console.error('磁盘内容变更订阅者失败', error);
    }
  }
}

/**
 * 开始同步 (项目打开后调用一次, 见 `ui/EditorPage.svelte`)。
 *
 * 监听与 git 状态刷新共用同一条 (`lib/project-watch.ts` 是幂等的), 这里再起一次是为了不依赖
 * "git 那条一定起得来" —— 监听起不来时, 窗口聚焦与显式动作仍然能兜住。
 */
export async function startDiskSync(root: string): Promise<void> {
  if (!unsubscribeWatch) unsubscribeWatch = onProjectFilesChanged(onFilesChanged);
  if (!focusBound && typeof window !== 'undefined') {
    window.addEventListener('focus', onWindowFocus);
    focusBound = true;
  }
  await startProjectWatch(root);
  await checkAllOpenDocuments();
}

/** 停止同步并清空基准与冲突 (关闭项目 / 编辑页卸载时调用)。 */
export function stopDiskSync(): void {
  unsubscribeWatch?.();
  unsubscribeWatch = null;
  if (focusBound && typeof window !== 'undefined') {
    window.removeEventListener('focus', onWindowFocus);
    focusBound = false;
  }
  baselines.clear();
  diskSync.conflicts = {};
  diskSync.activePath = null;
}

/**
 * 同步"当前活动文档"。切换活动文档时调用。
 *
 * 三件事: ① 用户按过 Esc 那个决定只对"当时那一刻"有效 —— 切走再切回来意味着现在可以处理了,
 * 于是重新把对话框摆出来; ② 对刚切到的这一份**补查一次磁盘** (监听可能漏事件, 而"用户切过来
 * 看"正是最该确认它是不是最新的时刻); ③ 顺手清掉已关闭文档的基准与冲突 (不必让每个关闭入口
 * 都来调一次 `forget`)。
 */
export function setActiveDocument(path: string | null): void {
  diskSync.activePath = path;
  prune();
  if (!path) return;
  const conflict = diskSync.conflicts[keyOf(path)];
  if (conflict?.dismissed) conflict.dismissed = false;
  void checkPaths([path]);
}

/** 检查全部打开中的文档 (还原 / 切分支 / 切模板之后显式调用)。 */
export function checkAllOpenDocuments(): Promise<void> {
  return checkPaths(useAppStore.getState().documents.map((doc) => doc.path));
}

function checkPaths(paths: readonly string[]): Promise<void> {
  if (paths.length === 0) return queue;
  const targets = [...paths];
  queue = queue
    .then(async () => {
      prune();
      for (const path of targets) await checkDocument(path);
    })
    .catch((error) => {
      console.error('磁盘变更检查失败', error);
    });
  return queue;
}

async function checkDocument(path: string): Promise<void> {
  if (!useAppStore.getState().documents.some((item) => item.path === path)) return;
  let disk: string;
  try {
    disk = await fs.readTextLossy(path);
  } catch {
    /*
     * 读不到 (已被删除 / 权限不足): **不动编辑器**。内存里那份仍然有效, 用户保存时会重新创建
     * 文件 —— 把文档关掉或清空都比这激进得多。
     */
    return;
  }
  /*
   * 读盘是异步的: 这期间用户可能又敲了字、文档也可能被关掉, 因此决策一律用**现在**的状态,
   * 不能用进入本函数时抓到的那一份。
   */
  const doc = useAppStore.getState().documents.find((item) => item.path === path);
  if (!doc) return;

  const key = keyOf(path);
  const diskHash = contentHash(disk);
  const action = decideDiskAction({
    diskHash,
    baseHash: baselines.get(key),
    memHash: contentHash(doc.content),
    dirty: doc.dirty,
  });

  if (action === 'ignore') return;
  if (action === 'adopt') {
    baselines.set(key, diskHash);
    return;
  }
  if (action === 'conflict') {
    recordConflict(path, disk, diskHash);
    return;
  }
  reloadFromDisk(path, disk, diskHash);
}

/** 干净文档: 直接换成磁盘那一份 (编辑器经 `doc.content` 那条回灌通道跟随)。 */
function reloadFromDisk(path: string, disk: string, diskHash: string): void {
  const key = keyOf(path);
  baselines.set(key, diskHash);
  delete diskSync.conflicts[key];
  useAppStore.getState().updateDocument(path, { content: disk, dirty: false });
  emitExternalContent(path);
}

function recordConflict(path: string, disk: string, diskHash: string): void {
  const key = keyOf(path);
  const previous = diskSync.conflicts[key];
  diskSync.conflicts[key] = {
    path,
    hash: diskHash,
    preview: previewOf(disk),
    diskContent: disk,
    // 同一份磁盘内容只问一次: 用户按过 Esc 就不再打断, 磁盘再变时重新问
    dismissed: previous?.hash === diskHash ? previous.dismissed : false,
  };
}

/**
 * 裁决一条冲突。
 *
 * 「保留编辑器内容」必须**写盘**: 只"保留"而不写, 磁盘上还是被外部改过的那一份, 下一次检查会
 * 再问一遍, 用户陷入"每次都选保留、每次都被问"的死循环。
 *
 * 「备份后加载磁盘」是**两条路各取一半**: 把编辑器这一份另存到同目录 (用户回头还能找回自己的
 * 字), 再把磁盘那一份加载进编辑器 —— 它**不写**原文件, 否则"加载磁盘"就变成了"用编辑器覆盖磁盘"。
 */
export async function resolveConflict(path: string, choice: ConflictChoice): Promise<void> {
  const conflict = diskSync.conflicts[keyOf(path)];
  if (!conflict) return;

  const store = useAppStore.getState();
  if (choice === 'keep-editor') {
    const memory = store.documents.find((item) => item.path === path)?.content ?? '';
    await fs.writeText(path, memory);
    store.updateDocument(path, { dirty: false });
    noteDiskContent(path, memory);
  } else {
    if (choice === 'backup-take-disk') {
      const memory = store.documents.find((item) => item.path === path)?.content ?? '';
      // 备份放在**同目录**下: 用户回头要找它, 放在项目里才找得到 (后缀不是 `.txt`, 不会被当成场景)
      await fs.writeText(backupPathOf(path), memory);
    }
    store.updateDocument(path, { content: conflict.diskContent, dirty: false });
    noteDiskContent(path, conflict.diskContent);
  }

  delete diskSync.conflicts[keyOf(path)];
  emitExternalContent(path);
}

/** 备份文件路径: 同目录 + 时间戳后缀。 */
function backupPathOf(path: string): string {
  const separator = path.includes('\\') ? '\\' : '/';
  const cut = path.lastIndexOf(separator);
  const directory = cut > 0 ? path.slice(0, cut) : '';
  const name = path.slice(cut + 1);
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  return `${directory}${separator}${name}.ink-backup-${stamp}`;
}

/** 项目文件监听: 只挑真正变化的打开文档。 */
function onFilesChanged(paths: string[]): void {
  const targets = affectedDocumentPaths(useAppStore.getState().documents, paths);
  if (targets.length === 0) return;
  void checkPaths(targets);
}

/**
 * 窗口重新获得焦点时补一次。
 *
 * 兜住两类漏报: 原子替换式保存 (写临时文件再 rename) 有时只报临时文件名; 睡眠唤醒后事件可能
 * 整段丢失。
 */
function onWindowFocus(): void {
  const now = Date.now();
  if (now - lastFocusCheck < 1000) return;
  lastFocusCheck = now;
  void checkAllOpenDocuments();
}

/** 丢掉已关闭文档的基准与冲突。 */
function prune(): void {
  const open = new Set(useAppStore.getState().documents.map((doc) => keyOf(doc.path)));
  for (const key of [...baselines.keys()]) {
    if (!open.has(key)) baselines.delete(key);
  }
  for (const key of Object.keys(diskSync.conflicts)) {
    if (!open.has(key)) delete diskSync.conflicts[key];
  }
}
